/*!
 * @loomui/ui theme — generated by tools/build-theme-css.mjs. Import once in your global stylesheet AFTER tailwindcss:
 *
 *   @import 'tailwindcss';
 *   @import '@loomui/ui/styles/loomui.css';
 *
 *   (class scanning of the package is configured inside this file via @source)
 *
 * Add class="dark" to <html> for dark mode; add e.g. class="theme-blue" for an accent preset.
 */
@import 'tw-animate-css';
@import '@angular/cdk/overlay-prebuilt.css';

/* Let Tailwind scan this package's compiled components for class names. */
@source "../";

@custom-variant dark (&:is(.dark *):not(:is(.force-light *)));
/* shadcn's current styles use data-open:/data-closed: next to Radix's data-state. Map both. */
@custom-variant data-open (&:where([data-state="open"], [data-open]));
@custom-variant data-closed (&:where([data-state="closed"], [data-closed]));
@custom-variant data-checked (&:where([data-state="checked"], [data-checked]));
@custom-variant data-unchecked (&:where([data-state="unchecked"], [data-unchecked]));
@custom-variant data-active (&:where([data-state="active"], [data-active]));
@custom-variant data-inactive (&:where([data-state="inactive"], [data-inactive]));
@custom-variant data-horizontal (&:where([data-orientation="horizontal"], [data-horizontal]));
@custom-variant data-vertical (&:where([data-orientation="vertical"], [data-vertical]));

:root,
.force-light {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.809 0.105 251.813);
  --chart-2: oklch(0.623 0.214 259.815);
  --chart-3: oklch(0.546 0.245 262.881);
  --chart-4: oklch(0.488 0.243 264.376);
  --chart-5: oklch(0.424 0.199 265.638);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  /* Native <select> popups are drawn by the browser: a transparent/tinted select would get a white list with light text.
     Give options an explicit surface so they are readable in light and dark. */
  select option,
  select optgroup {
    background-color: var(--popover);
    color: var(--popover-foreground);
  }
}

/* CDK overlay backdrop: shadcn animates the backdrop with tw-animate-css, so neutralise the CDK opacity fade. */
.cdk-overlay-backdrop[data-slot] {
  opacity: 1;
  transition: none;
}

.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* input-otp fake caret */
@theme inline {
  --animate-caret-blink: caret-blink 1.25s ease-out infinite;
}
@keyframes caret-blink {
  0%,
  70%,
  100% {
    opacity: 1;
  }
  20%,
  50% {
    opacity: 0;
  }
}

/* ---------- Accent presets (class on <html>, combine with .dark) ---------- */
.theme-blue { --primary: oklch(0.546 0.245 262.881); --primary-foreground: oklch(0.985 0 0); --ring: oklch(0.623 0.214 259.815); --sidebar-primary: var(--primary); }
.dark.theme-blue { --primary: oklch(0.623 0.214 259.815); --ring: oklch(0.546 0.245 262.881); }
.theme-rose { --primary: oklch(0.586 0.253 17.585); --primary-foreground: oklch(0.985 0 0); --ring: oklch(0.645 0.246 16.439); --sidebar-primary: var(--primary); }
.dark.theme-rose { --primary: oklch(0.645 0.246 16.439); --ring: oklch(0.586 0.253 17.585); }
.theme-green { --primary: oklch(0.627 0.194 149.214); --primary-foreground: oklch(0.985 0 0); --ring: oklch(0.723 0.219 149.579); --sidebar-primary: var(--primary); }
.dark.theme-green { --primary: oklch(0.696 0.17 162.48); --primary-foreground: oklch(0.205 0 0); --ring: oklch(0.627 0.194 149.214); }
.theme-orange { --primary: oklch(0.646 0.222 41.116); --primary-foreground: oklch(0.985 0 0); --ring: oklch(0.705 0.213 47.604); --sidebar-primary: var(--primary); }
.dark.theme-orange { --primary: oklch(0.705 0.213 47.604); --primary-foreground: oklch(0.205 0 0); --ring: oklch(0.646 0.222 41.116); }
.theme-violet { --primary: oklch(0.541 0.281 293.009); --primary-foreground: oklch(0.985 0 0); --ring: oklch(0.606 0.25 292.717); --sidebar-primary: var(--primary); }
.dark.theme-violet { --primary: oklch(0.606 0.25 292.717); --ring: oklch(0.541 0.281 293.009); }
:is(.theme-blue, .theme-rose, .theme-green, .theme-orange, .theme-violet) {
  --chart-1: color-mix(in oklab, var(--primary) 55%, white);
  --chart-2: color-mix(in oklab, var(--primary) 80%, white);
  --chart-3: var(--primary);
  --chart-4: color-mix(in oklab, var(--primary) 78%, black);
  --chart-5: color-mix(in oklab, var(--primary) 58%, black);
}

/* ---- Toast (ui-toaster) ---- */
/* Styles for <ui-toaster>. Sonner ships its own injected CSS; this is the equivalent for the same data-* attributes.
   Import once: @import '<path>/libs/ui/toast/toast.css'; */

ui-toaster {
  display: contents;
}

[data-sonner-toaster] {
  position: fixed;
  z-index: 999999999;
  width: var(--width);
  margin: 0;
  padding: 0;
  list-style: none;
  outline: none;
  pointer-events: none;
}

[data-sonner-toaster][data-x-position='right'] { right: var(--offset-right); }
[data-sonner-toaster][data-x-position='left'] { left: var(--offset-left); }
[data-sonner-toaster][data-x-position='center'] { left: 50%; transform: translateX(-50%); }
[data-sonner-toaster][data-y-position='bottom'] { bottom: var(--offset-bottom); }
[data-sonner-toaster][data-y-position='top'] { top: var(--offset-top); }

@media (max-width: 600px) {
  [data-sonner-toaster] {
    width: calc(100% - 32px);
    left: 16px !important;
    right: 16px !important;
    transform: none !important;
  }
}

[data-sonner-toast] {
  --lift: -1;
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  box-sizing: border-box;
  width: 100%;
  padding: 16px;
  border: 1px solid var(--normal-border);
  border-radius: var(--border-radius);
  background: var(--normal-bg);
  color: var(--normal-text);
  font-size: 13px;
  line-height: 1.4;
  box-shadow: 0 4px 12px rgb(0 0 0 / 0.1);
  outline: none;
  pointer-events: auto;
  opacity: 0;
  z-index: var(--z-index);
  transition:
    transform 400ms,
    opacity 400ms;
  transform: translateY(calc(var(--lift) * -100%));
}

[data-sonner-toast][data-y-position='bottom'] { bottom: 0; --lift: -1; }
[data-sonner-toast][data-y-position='top'] { top: 0; --lift: 1; }

/* mounted + collapsed stack */
[data-sonner-toast][data-mounted='true'] {
  opacity: 1;
  transform: translateY(calc(var(--lift) * var(--index) * var(--gap)))
    scale(calc(1 - var(--index) * 0.05));
}
[data-sonner-toast][data-mounted='true']:not([data-front='true']) { transition-timing-function: ease; }

/* hidden beyond visibleToasts */
[data-sonner-toast][data-visible='false'] { opacity: 0; pointer-events: none; }

/* expanded stack: offsets measured in TS (--offset px) */
[data-sonner-toast][data-mounted='true'][data-expanded='true'] {
  transform: translateY(calc(var(--lift) * var(--offset)));
}
[data-sonner-toast][data-expanded='true'][data-visible='true'] { opacity: 1; }

/* removal */
[data-sonner-toast][data-removed='true'] {
  opacity: 0;
  pointer-events: none;
  transform: translateY(calc(var(--lift) * -1 * 100%));
}

/* keep hover alive across the gap between toasts */
[data-sonner-toast]::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: calc(var(--gap) + 1px);
  bottom: 100%;
}
[data-sonner-toast][data-y-position='top']::after { top: 100%; bottom: auto; }

[data-sonner-toast] [data-content] { display: flex; flex-direction: column; gap: 2px; flex: 1; }
[data-sonner-toast] [data-title] { font-weight: 500; }
[data-sonner-toast] [data-description] { color: var(--muted-foreground); }

[data-sonner-toast] [data-icon] { display: flex; width: 16px; height: 16px; }
[data-sonner-toast] [data-icon] svg { width: 16px; height: 16px; }
[data-sonner-toast][data-type='success'] [data-icon] { color: oklch(0.627 0.194 149.2); }
[data-sonner-toast][data-type='error'] [data-icon] { color: var(--destructive); }
[data-sonner-toast][data-type='warning'] [data-icon] { color: oklch(0.769 0.188 70.08); }
[data-sonner-toast] [data-icon] svg[data-spin='true'] { animation: ui-toast-spin 1s linear infinite; }

[data-sonner-toast] [data-button] {
  flex-shrink: 0;
  height: 24px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: var(--primary);
  color: var(--primary-foreground);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
[data-sonner-toast] [data-button]:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

@keyframes ui-toast-spin { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
  [data-sonner-toast] { transition-duration: 1ms; }
}
